from imp import reloadimport mathz = input('Please give me a number: ')z = int(z)count = 0a = [0,0,0]for r in range(3,z):    i = 2    isprime = True    d = 0    while (i <= r-1):        if r%i==0 :            isprime = False            d = d +1        i+=1        count = count + isprime    a = a+[d]print("The vector is:",a)import matplotlib.pyplot as pltplt.plot(a)plt.show()